import React, { useState, useMemo, useEffect } from 'react';
import { useTheme, useMediaQuery } from '@mui/material';
import { useNavigate } from 'react-router-dom';
import useUser from '../../../core/hooks/useUser';
import useApp from '../../../utils/useApp';
import { useGetUserQuery } from '../../../page/posApi';
import { IUser, IUserInfo } from '../../../core/Interface/user.interface';
import { fullPageRoutes } from '../constants';
import { MenuItem } from '../types';
import { isEffectivelyEmpty } from '../../../core/utils';

export function useDrawerState() {
  const theme = useTheme();
  /* tablets (< 900 px) and phones get the temporary overlay drawer */
  const isSmall = useMediaQuery(theme.breakpoints.down('md'));
  const isDesktop = useMediaQuery(theme.breakpoints.up('lg'));
  const [open, setOpen] = useState(isDesktop);

  useEffect(() => {
    setOpen(isDesktop);
  }, [isDesktop]);

  const { userHasRight } = useUser();
  const navigate = useNavigate();
  const { currentMenuName } = useApp();
  const { data } = useGetUserQuery();
  const [expandMenu, setExpandMenu] = useState<string>('');
  const [profile, setProfile] = useState<HTMLElement | null>(null);

  const userName = useMemo((): string | false => {
    if (data?.data) {
      const userData = data.data as IUser;
      return userData.username;
    }
    return false;
  }, [data]);

  const companyName = useMemo((): string | false => {
    if (data?.data) {
      const userData = data.data as IUserInfo;
      if (userData.company) return userData.company.name;
    }
    return false;
  }, [data]);

  const branchName = useMemo(() => {
    if (data?.data) {
      const userData = data.data as IUserInfo;
      return userData.branch.name;
    }
    return '';
  }, [data]);

  const noticeText = useMemo(() => {
    if (data?.data) {
      const noticeTextData = data.data as IUserInfo;
      return noticeTextData.noticeText;
    }
    return '';
  }, [data]);

  const hasNotice = useMemo(() => !isEffectivelyEmpty(noticeText), [noticeText]);

  const userImageUrl = useMemo(() => {
    if (data?.data) {
      const userData = data.data as IUserInfo;
      return userData.imageUrl;
    }
    return '';
  }, [data]);

  const isFullPage = fullPageRoutes.includes(currentMenuName);
  const hideDrawer = isFullPage;

  const handleDrawerOpen = () => setOpen(true);
  const handleDrawerClose = () => setOpen(false);

  const handleProfileClick = (event: React.MouseEvent<HTMLButtonElement>) => {
    setProfile(event.currentTarget);
  };
  const handleProfileClose = () => setProfile(null);

  const handleMainMenuItemClick = (ml: MenuItem) => {
    if (ml.submenus && ml.submenus.length > 0) {
      ml.title === expandMenu ? setExpandMenu('') : setExpandMenu(ml.title);
    } else if (ml.path) {
      navigate(ml.path);
    }
  };

  useEffect(() => {
    if (fullPageRoutes.includes(currentMenuName)) setOpen(true);
  }, [currentMenuName]);

  return {
    theme,
    isSmall,
    open,
    setOpen,
    userHasRight,
    navigate,
    currentMenuName,
    expandMenu,
    profile,
    handleProfileClick,
    handleProfileClose,
    userName,
    companyName,
    branchName,
    noticeText,
    hasNotice,
    userImageUrl,
    isFullPage,
    hideDrawer,
    handleDrawerOpen,
    handleDrawerClose,
    handleMainMenuItemClick,
  };
}
