import { Box, Chip, Grid, IconButton, Typography } from '@mui/material';
import * as React from 'react';
import DeleteOutlinedIcon from '@mui/icons-material/DeleteOutlined';
import { appColors } from '../../../theme/appColors';
import { useSelector } from 'react-redux';
import { selectBasketItems } from '../store/BasketSelector';
import { useAppDispatch } from '../../../store/hooks';
import { editBasket, removeItem } from '../store/BasketSlice';
import { getPriceFormatWithoutCurrency } from '../../../core/utils';
import { useState } from 'react';
import AlertPopup from './Kgpopup';
import { IJewelleryBasketItem } from '../../../core/Interface/saleJewellery.interface';

const NAVY = '#0F1D4D';

const ItemCard = () => {
  const dispatch = useAppDispatch();
  const selectItem = useSelector(selectBasketItems);

  const [selectedProduct, setSelectedProduct] = useState<IJewelleryBasketItem | null>(null);
  const [openShowPopup, setOpenShowPopup] = useState(false);

  const handleAddEdit = (
    calculatedValue: number | null,
    inputCount: number,
    goldData?: {
      goldWeightQty: number;
      goldWasteQty: number;
      goldCarrot: string;
      makingCharge: number;
      goldPrice8g: number;
    }
  ) => {
    if (selectedProduct && calculatedValue !== null) {
      const basketItem: IJewelleryBasketItem = {
        ...selectedProduct,
        unitPrice: calculatedValue,
        calculatedUnitPrice: calculatedValue,
        count: inputCount || 1,
        goldWeightQty: goldData?.goldWeightQty ?? 0,
        goldWasteQty: goldData?.goldWasteQty ?? 0,
        goldCarrot: goldData?.goldCarrot ?? '22K',
        makingCharge: goldData?.makingCharge ?? 0,
        goldPrice8g: goldData?.goldPrice8g ?? 0,
      };
      dispatch(editBasket(basketItem));
      setOpenShowPopup(false);
    }
  };

  if (selectItem.length === 0) {
    return (
      <Box
        sx={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          height: '100%',
          opacity: 0.35,
        }}
      >
        <Typography sx={{ fontSize: 13, color: appColors.royalBlue[60] }}>
          No items added yet
        </Typography>
      </Box>
    );
  }

  return (
    <Box
      sx={{
        height: '100%',
        overflowY: 'auto',
        scrollbarWidth: 'thin',
        '&::-webkit-scrollbar': { width: '3px' },
        '&::-webkit-scrollbar-thumb': { backgroundColor: '#94a3b8', borderRadius: '2px' },
        p: '4px 8px 0 8px',
      }}
    >
      {selectItem
        .slice()
        .reverse()
        .map((item) => {
          const productPrice =
            (item.goldWeightQty ?? 0) * ((item.goldPrice8g ?? 0) / 8) +
            (item.makingCharge ?? 0) +
            (item.goldWasteQty ?? 0) * ((item.goldPrice8g ?? 0) / 8);

          return (
            <Grid
              alignItems="center"
              container
              key={item.id}
              onClick={() => {
                setSelectedProduct(item);
                setOpenShowPopup(true);
              }}
              spacing={1}
              sx={{
                py: '6px',
                px: '4px',
                cursor: 'pointer',
                borderBottom: `1px solid ${appColors.darkGray[10]}`,
                '&:last-child': { borderBottom: 'none' },
                flexWrap: 'nowrap',
                borderRadius: '6px',
                transition: 'background 0.15s ease',
                '&:hover': { backgroundColor: appColors.reflexBlue[10] },
              }}
            >
              {/* Item name */}
              <Grid item xs={4} md={4}>
                <Typography
                  sx={{
                    fontSize: 13,
                    fontWeight: 500,
                    color: NAVY,
                    lineHeight: 1.2,
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    whiteSpace: 'nowrap',
                  }}
                >
                  {item.name}
                </Typography>
              </Grid>

              {/* Qty chip */}
              <Grid item xs={2} md={2}>
                <Box sx={{ display: 'flex', justifyContent: 'flex-end' }}>
                  <Chip
                    label={item.count}
                    size="small"
                    sx={{
                      height: 20,
                      fontSize: 11,
                      fontWeight: 700,
                      backgroundColor: appColors.reflexBlue[100],
                      color: appColors.white,
                      '& .MuiChip-label': { px: '6px' },
                    }}
                  />
                </Box>
              </Grid>

              {/* Weight */}
              <Grid item xs={2} md={2}>
                <Typography
                  align="right"
                  sx={{ fontSize: 13, color: appColors.royalBlue[80], fontVariantNumeric: 'tabular-nums' }}
                >
                  {item.goldWeightQty ?? 0}g
                </Typography>
              </Grid>

              {/* Amount */}
              <Grid item xs={3} md={3}>
                <Typography
                  align="right"
                  sx={{ fontSize: 13, color: appColors.royalBlue[80], fontVariantNumeric: 'tabular-nums' }}
                >
                  {getPriceFormatWithoutCurrency(productPrice)}
                </Typography>
              </Grid>

              {/* Delete */}
              <Grid item xs={1} md={1}>
                <Box sx={{ display: 'flex', justifyContent: 'flex-end' }}>
                  <IconButton
                    onClick={(e) => {
                      e.stopPropagation();
                      dispatch(removeItem(item.id));
                    }}
                    size="small"
                    sx={{ p: '2px', color: appColors.carmineRed[30], '&:hover': { color: appColors.carmineRed[60] } }}
                  >
                    <DeleteOutlinedIcon sx={{ fontSize: 15 }} />
                  </IconButton>
                </Box>
              </Grid>
            </Grid>
          );
        })}

      {selectedProduct && openShowPopup && (
        <AlertPopup
          editGoldData={{
            goldWeightQty: selectedProduct.goldWeightQty || 0,
            goldWasteQty: selectedProduct.goldWasteQty || 0,
            goldCarrot: selectedProduct.goldCarrot || '',
            makingCharge: selectedProduct.makingCharge || 0,
            goldPrice8g: selectedProduct.goldPrice8g || 0,
          }}
          handleAdd={handleAddEdit}
          handleCloseAlert={() => setOpenShowPopup(false)}
          open={openShowPopup}
          product={selectedProduct}
        />
      )}
    </Box>
  );
};

export default React.memo(ItemCard);
