import React from 'react';
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Stack,
  Typography,
} from '@mui/material';
import HelpOutlineRoundedIcon from '@mui/icons-material/HelpOutlineRounded';
import { useTranslation } from 'react-i18next';
import { HEADER_GRADIENT } from '../../theme/appColors';

interface IConfirmationModel {
  open: boolean;
  handleClose: (close: boolean) => void;
  onConfirm: () => void;
  title: string;
  content: string;
  isProcessing?: boolean;
}

const ConfirmationModel = ({
  open,
  handleClose,
  onConfirm,
  title,
  content,
  isProcessing,
}: IConfirmationModel) => {
  const { t } = useTranslation(['common']);

  const onClose = () => handleClose(false);

  return (
    <Dialog
      onClose={onClose}
      open={open}
      PaperProps={{
        sx: {
          borderRadius: '12px',
          overflow: 'hidden',
          width: 440,
          maxWidth: 'calc(100vw - 32px)',
        },
      }}
    >
      <DialogTitle sx={{ p: 0 }}>
        <Box sx={{ background: HEADER_GRADIENT, px: 3, py: 2 }}>
          <Stack alignItems="center" direction="row" spacing={1.5}>
            <Box
              sx={{
                alignItems: 'center',
                background: 'rgba(255,255,255,0.15)',
                borderRadius: '8px',
                display: 'flex',
                height: 36,
                justifyContent: 'center',
                width: 36,
                flexShrink: 0,
              }}
            >
              <HelpOutlineRoundedIcon sx={{ color: '#fff', fontSize: 20 }} />
            </Box>
            <Box>
              <Typography sx={{ color: '#fff', fontSize: '1rem', fontWeight: 800, lineHeight: 1.2 }}>
                {title}
              </Typography>
              <Typography sx={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.72rem', fontWeight: 500 }}>
                Confirmation required
              </Typography>
            </Box>
          </Stack>
        </Box>
      </DialogTitle>

      <DialogContent sx={{ px: 3, pt: 2.5, pb: 1 }}>
        <Typography sx={{ color: '#475569', fontSize: '0.92rem', lineHeight: 1.6 }}>
          {content}
        </Typography>
      </DialogContent>

      <DialogActions sx={{ borderTop: '1px solid #E2E8F0', gap: 1.5, px: 3, py: 2 }}>
        <Button
          autoFocus
          onClick={onClose}
          sx={{
            borderColor: '#CBD5E1',
            borderRadius: '8px',
            color: '#475569',
            fontWeight: 600,
            height: 40,
            minWidth: 110,
            px: 3,
            textTransform: 'none',
            '&:hover': { background: '#F1F5F9', borderColor: '#94A3B8' },
          }}
          variant="outlined"
        >
          {t('common:no')}
        </Button>
        <Button
          disabled={isProcessing}
          onClick={onConfirm}
          sx={{
            background: HEADER_GRADIENT,
            borderRadius: '8px',
            boxShadow: '0 4px 14px rgba(15,29,77,0.25)',
            color: '#fff',
            fontWeight: 700,
            height: 40,
            minWidth: 110,
            px: 3,
            textTransform: 'none',
            '&:hover': { opacity: 0.9 },
            '&.Mui-disabled': { background: '#CBD5E1', color: '#94A3B8' },
          }}
          variant="contained"
        >
          {t('common:yes')}
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default ConfirmationModel;
