import { Box, Divider, Grid, Typography } from '@mui/material';
import * as React from 'react';
import { appColors, HEADER_GRADIENT } from '../../../theme/appColors';
import { getPriceFormatWithoutCurrency } from '../../../core/utils';
import { useTranslation } from 'react-i18next';

const row = (label: string, value: string) => (
  <Grid container sx={{ py: '3px' }}>
    <Grid item xs={6}>
      <Typography
        sx={{
          fontSize: 12,
          fontWeight: 600,
          color: appColors.white,
          textTransform: 'uppercase',
          letterSpacing: '0.4px',
        }}
      >
        {label}
      </Typography>
    </Grid>
    <Grid item xs={6}>
      <Typography
        align="right"
        sx={{
          fontSize: 12,
          fontWeight: 600,
          color: appColors.white,
          fontVariantNumeric: 'tabular-nums',
        }}
      >
        {value}
      </Typography>
    </Grid>
  </Grid>
);

const Summary = ({
  subtotal,
  discount,
  total,
  currencyCode,
}: {
  subtotal: number;
  discount: number;
  total: number;
  currencyCode: string;
}) => {
  const { t } = useTranslation(['sales']);

  return (
    <Box sx={{ background: HEADER_GRADIENT, px: '14px', pt: '10px', pb: '12px' }}>
      {row(t('sales:subtotal'), getPriceFormatWithoutCurrency(subtotal))}
      {row(t('sales:discount'), `- ${getPriceFormatWithoutCurrency(discount)}`)}

      <Divider sx={{ borderColor: 'rgba(255,255,255,0.2)', my: '8px' }} />

      {/* Net Total — prominent */}
      <Grid alignItems="center" container>
        <Grid item xs={5}>
          <Typography
            sx={{
              fontSize: 13,
              fontWeight: 800,
              color: appColors.white,
              textTransform: 'uppercase',
              letterSpacing: '0.6px',
            }}
          >
            {t('sales:total')}
          </Typography>
          {currencyCode && (
            <Typography sx={{ fontSize: 10, color: 'rgba(255,255,255,0.75)', fontWeight: 500 }}>
              {currencyCode}
            </Typography>
          )}
        </Grid>
        <Grid item xs={7}>
          <Typography
            align="right"
            sx={{
              fontSize: 18,
              fontWeight: 900,
              color: appColors.white,
              fontVariantNumeric: 'tabular-nums',
              lineHeight: 1,
            }}
          >
            {getPriceFormatWithoutCurrency(total)}
          </Typography>
        </Grid>
      </Grid>
    </Box>
  );
};

export default React.memo(Summary);
